// ELEMENTS:
// 1. Navy com o filete vermelho no topo
// 2. Eyebrow + título (anim.text)
// 3. Ilustração de um prédio de 3 pisos: primeiro velho (traço tracejado, fissuras), depois sobe um
//    andaime, e um varrimento da esquerda para a direita deixa-o reabilitado a cores (paredes azul-claro,
//    janelas azul royal, telhado vermelho) enquanto o andaime desaparece
// 4. Carimbo redondo vermelho (stamp) a cair em stampAt (s); sub em névoa
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const TINT = "#E8EEF9";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(2));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.07, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const WINDOWS = [0, 1, 2].flatMap((row) => [0, 1, 2].map((col) => ({ x: 92 + col * 80, y: 130 + row * 100 })));

const ReabilitacaoAntesDepois: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const cid = useId().replace(/:/g, "");
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const stampText = String(p.stamp ?? "").trim();
  const stampAt = Number(p.stampAt ?? 2.8) || 2.8;
  const title = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const old = show(0, 0.8);
  const scaffold = show(0.7, 0.8);
  const sweep = show(1.5, 1.2, Easing.inOut(Easing.cubic));
  const stamp = show(stampAt, 0.45, BACK);
  const dash = { pathLength: 1, strokeDasharray: 1 };

  const building = (renewed: boolean) => (
    <g>
      <path d="M60 100 L200 30 L340 100 Z" fill={renewed ? RED : "none"} stroke={renewed ? RED : "rgba(255,255,255,0.55)"} strokeWidth={4} strokeLinejoin="round" strokeDasharray={renewed ? undefined : "10 8"} />
      <rect x={70} y={100} width={260} height={330} fill={renewed ? TINT : "none"} stroke={renewed ? TINT : "rgba(255,255,255,0.55)"} strokeWidth={4} strokeDasharray={renewed ? undefined : "10 8"} />
      {WINDOWS.map((w, i) => (
        <rect key={i} x={w.x} y={w.y} width={56} height={70} rx={4} fill={renewed ? BLUE : "none"} stroke={renewed ? BLUE : "rgba(255,255,255,0.45)"} strokeWidth={3} strokeDasharray={renewed ? undefined : "6 6"} />
      ))}
      <rect x={176} y={350} width={48} height={80} rx={4} fill={renewed ? NAVY : "none"} stroke={renewed ? NAVY : "rgba(255,255,255,0.45)"} strokeWidth={3} />
      {renewed ? null : (
        <path d="M110 110 L124 140 L112 160 L130 196 M300 260 L286 290 L298 312 L282 340" fill="none" stroke={MIST} strokeWidth={3} strokeLinecap="round" {...dash} strokeDashoffset={1 - old} />
      )}
    </g>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 40 * u }}>
        {eyebrow ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 30 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: MIST, opacity: show(0.05) }}>
            <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
            {eyebrow}
          </div>
        ) : null}
        <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 100 * u, lineHeight: 1.05, color: WHITE, textAlign: "center", opacity: show(0.15), transform: `translateY(${(1 - show(0.15)) * 26 * u}px)` }}>{title}</div>
        <div style={{ position: "relative" }}>
          <svg width={700 * u} height={800 * u} viewBox="0 0 400 460" style={{ overflow: "visible" }}>
            <defs>
              <clipPath id={cid}><rect x={0} y={0} width={400 * sweep} height={460} /></clipPath>
            </defs>
            <g opacity={old}>{building(false)}</g>
            <g opacity={scaffold * (1 - sweep * 0.9)}>
              {[50, 130, 210, 290, 350].map((x, i) => <line key={i} x1={x} y1={440} x2={x} y2={440 - 400 * scaffold} stroke={WHITE} strokeWidth={3} />)}
              {[110, 210, 310, 410].map((y, i) => <line key={i} x1={44} y1={y} x2={44 + 312 * scaffold} y2={y} stroke={WHITE} strokeWidth={3} />)}
            </g>
            <g clipPath={`url(#${cid})`}>{building(true)}</g>
            <line x1={400 * sweep} y1={10} x2={400 * sweep} y2={450} stroke={WHITE} strokeWidth={4} opacity={sweep > 0 && sweep < 1 ? 0.9 : 0} />
            <line x1={20} y1={432} x2={380} y2={432} stroke="rgba(255,255,255,0.5)" strokeWidth={3} />
          </svg>
          {stampText ? (
            <div style={{ position: "absolute", right: -40 * u, top: 60 * u, width: 230 * u, height: 230 * u, borderRadius: "50%", background: RED, border: `${6 * u}px solid ${WHITE}`, color: WHITE, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", fontFamily: FONTS.body, fontWeight: 700, fontSize: 28 * u, letterSpacing: "0.1em", textTransform: "uppercase", lineHeight: 1.2, padding: 20 * u, boxSizing: "border-box", transform: `rotate(${-12 + (1 - stamp) * 30}deg) scale(${stamp > 0 ? 0.6 + 0.4 * stamp + (1 - stamp) : 0})`, opacity: stamp, boxShadow: "0 18px 40px rgba(0,0,0,0.4)" }}>
              <svg width={60 * u} height={44 * u} viewBox="0 0 60 44"><path d="M8 22 L24 36 L52 8" fill="none" stroke={WHITE} strokeWidth={7} strokeLinecap="round" strokeLinejoin="round" /></svg>
              {stampText}
            </div>
          ) : null}
        </div>
        {sub ? <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 48 * u, color: MIST, textAlign: "center", maxWidth: 880 * u, opacity: show(stampAt + 0.3) }}>{sub}</div> : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default ReabilitacaoAntesDepois;
